def square(n):
    return n * n

print(square(7))  # output: 49

def factorial(n):
    if n <= 1:
        return 1
    return n * factorial(n - 1)

print(factorial(5))  # output: 120

def max_of_two(a, b):
    if a > b:
        return a
    return b

print(max_of_two(12, 8))  # output: 12

def is_even(n):
    if n % 2 == 0:
        return "Even"
    return "Odd"

print(is_even(4))   # output: Even
print(is_even(7))   # output: Odd

def is_leap_year(year):
    if year % 4 == 0 and (year % 100 != 0 or year % 400 == 0):
        return True
    return False

print(is_leap_year(2024))  # output: True
print(is_leap_year(2023))  # output: False

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

print(gcd(48, 18))  # output: 6

def absolute(n):
    if n < 0:
        return -n
    return n

print(absolute(-5))  # output: 5

